/**
 * Anchor builder: turns a picked element into a PatchAnchor that finds that
 * element again later.
 *
 * Selector strategy (first one that is unique wins, and uniqueness is CHECKED
 * against the document, never assumed):
 *   1. a stable #id
 *   2. a stable attribute (data-testid, name, aria-label, ...)
 *   3. tag.class[.class] with :nth-of-type where siblings are ambiguous, climbing
 *      parents until the whole path matches exactly one element
 *
 * "Stable" means: not generated by a framework or CSS-in-JS tool (css-1a2b3c,
 * sc-bdVaJa, :r1:, ...) and not one of our own pw- markers.
 *
 * Pure DOM, no Chrome APIs: unit-tested in happy-dom.
 */
import type { PatchAnchor } from '@patchwork/shared';

/** The longest text hint we store. Longer text is cut; targeting then falls back to the unique selector. */
export const TEXT_CAP = 200;

const STABLE_ATTRIBUTES = ['data-testid', 'data-test', 'data-cy', 'data-qa', 'name', 'aria-label'];
const MAX_ATTR_VALUE = 80;
const MAX_CLASSES_PER_SEGMENT = 3;

// ---------- what counts as stable ----------

const GENERATED_PREFIX = /^(css|sc|jsx|svelte|emotion|styled|chakra|mui|radix|headlessui|react|ember|ng)[-_:]/i;

/** True for class names / ids that look machine-made and will change on the next build. */
export function looksGenerated(token: string): boolean {
  if (GENERATED_PREFIX.test(token)) return true;
  if (/^:r[0-9a-z]*:$/i.test(token)) return true; // React useId
  if (/\d{4,}/.test(token)) return true; // long digit runs (timestamps, counters)
  if (/[0-9a-f]{8,}/i.test(token) && /\d/.test(token)) return true; // hashes and uuids
  // short mixed-case-with-digit blobs such as _3xK9d2 or a1B2c3
  if (/^[_-]?[A-Za-z0-9]{5,8}$/.test(token) && /[a-z]/.test(token) && /[A-Z]/.test(token) && /\d/.test(token)) return true;
  return false;
}

const SAFE_TOKEN = /^[A-Za-z_][\w-]*$/;

function isStableToken(token: string): boolean {
  return SAFE_TOKEN.test(token) && !token.startsWith('pw-') && !looksGenerated(token);
}

export function stableClasses(el: Element): string[] {
  const raw = el.getAttribute('class') ?? '';
  return raw.split(/\s+/).filter((c) => c && isStableToken(c));
}

// ---------- escaping ----------

function cssEscape(value: string): string {
  const native = (globalThis as { CSS?: { escape?: (s: string) => string } }).CSS?.escape;
  if (native) return native(value);
  return value.replace(/[^\w-]/g, (c) => '\\' + c).replace(/^(\d)/, '\\3$1 ');
}

const quoteAttr = (value: string) => '"' + value.replace(/["\\]/g, '\\$&') + '"';

// ---------- selector building ----------

function isUnique(doc: Document, selector: string, el: Element): boolean {
  try {
    const found = doc.querySelectorAll(selector);
    return found.length === 1 && found[0] === el;
  } catch {
    return false; // an invalid selector is never a good answer
  }
}

function stableId(el: Element): string | null {
  return el.id && isStableToken(el.id) ? el.id : null;
}

function stableAttributeSelector(el: Element): string | null {
  const tag = el.tagName.toLowerCase();
  for (const name of STABLE_ATTRIBUTES) {
    const v = el.getAttribute(name);
    if (v && v.length <= MAX_ATTR_VALUE && !/[\r\n]/.test(v)) return `${tag}[${name}=${quoteAttr(v)}]`;
  }
  if (tag === 'a') {
    const href = el.getAttribute('href');
    if (href && href.length <= MAX_ATTR_VALUE && !href.includes('?') && !/[\r\n]/.test(href)) return `a[href=${quoteAttr(href)}]`;
  }
  return null;
}

/** tag + stable classes, no position. Used for parentContext and as the base of a path segment. */
function describe(el: Element): string {
  const classes = stableClasses(el).slice(0, MAX_CLASSES_PER_SEGMENT).map((c) => '.' + cssEscape(c));
  return el.tagName.toLowerCase() + classes.join('');
}

/** One step of a path: tag.class, plus :nth-of-type only when siblings would otherwise match it too. */
function segment(el: Element): string {
  const base = describe(el);
  const parent = el.parentElement;
  if (!parent) return base;
  const alike = Array.from(parent.children).filter((c) => c.matches(base));
  if (alike.length <= 1) return base;
  const sameTag = Array.from(parent.children).filter((c) => c.tagName === el.tagName);
  return `${base}:nth-of-type(${sameTag.indexOf(el) + 1})`;
}

export function buildSelector(el: Element): string {
  const doc = el.ownerDocument;
  const tag = el.tagName.toLowerCase();
  if (tag === 'html' || tag === 'body') return tag;

  const id = stableId(el);
  if (id && isUnique(doc, '#' + cssEscape(id), el)) return '#' + cssEscape(id);

  const attr = stableAttributeSelector(el);
  if (attr && isUnique(doc, attr, el)) return attr;

  // Climb: start with this element's segment, add parents until the path is unique AND anchored
  // (contains a class, attribute or id). A bare "span:nth-of-type(2)" is unique today but breaks as
  // soon as another span appears anywhere, so it is only the last resort.
  const anchored = (selector: string) => /[.#[]/.test(selector);
  let shortestUnique: string | null = null;
  const parts: string[] = [segment(el)];
  let cursor: Element | null = el;
  for (;;) {
    const selector = parts.join(' > ');
    if (isUnique(doc, selector, el)) {
      if (anchored(selector)) return selector;
      shortestUnique ??= selector;
    }
    cursor = cursor.parentElement;
    if (!cursor || cursor.tagName.toLowerCase() === 'html') break;
    const parentId = stableId(cursor);
    if (parentId && isUnique(doc, '#' + cssEscape(parentId), cursor)) {
      parts.unshift('#' + cssEscape(parentId)); // anchor the path at a stable id and stop
      const rooted = parts.join(' > ');
      if (isUnique(doc, rooted, el)) return rooted;
      break;
    }
    parts.unshift(segment(cursor));
  }
  // Nothing anchored was unique (a page of bare tags): use the shortest unique path, else the full one.
  return shortestUnique ?? parts.join(' > ');
}

// ---------- xpath ----------

export function buildXPath(el: Element): string {
  const steps: string[] = [];
  let cursor: Element | null = el;
  while (cursor && cursor.nodeType === 1) {
    const id = stableId(cursor);
    if (id) {
      // `steps` holds only the path below this element; the stable id replaces everything above it.
      return `//*[@id="${id}"]` + (steps.length ? '/' + steps.join('/') : '');
    }
    const tag = cursor.tagName.toLowerCase();
    const sameTag = cursor.parentElement ? Array.from(cursor.parentElement.children).filter((c) => c.tagName === cursor!.tagName) : [cursor];
    steps.unshift(sameTag.length > 1 ? `${tag}[${sameTag.indexOf(cursor) + 1}]` : tag);
    cursor = cursor.parentElement;
  }
  return '/' + steps.join('/');
}

// ---------- the rest of the anchor ----------

const collapse = (s: string | null | undefined) => (s ?? '').replace(/\s+/g, ' ').trim();

export function textHint(el: Element): string {
  return collapse(el.textContent).slice(0, TEXT_CAP);
}

function collectAttributes(el: Element): Record<string, string> {
  const out: Record<string, string> = {};
  for (const attr of Array.from(el.attributes)) {
    const name = attr.name;
    if (name === 'style' || name === 'pw-find' || name.startsWith('pw-')) continue;
    const keep = name === 'id' || name === 'class' || name === 'name' || name === 'role' || name === 'type' || name === 'aria-label' || name.startsWith('data-');
    if (!keep || attr.value.length > 100) continue;
    if (name === 'class') {
      const cleaned = attr.value.split(/\s+/).filter((c) => c && !c.startsWith('pw-')).join(' ');
      if (cleaned) out.class = cleaned;
    } else {
      out[name] = attr.value;
    }
    if (Object.keys(out).length >= 12) break;
  }
  return out;
}

/** Tags of the previous and next element siblings (what the shared matcher compares). */
function siblingTags(el: Element): string[] {
  const tags = [el.previousElementSibling, el.nextElementSibling].filter((s): s is Element => !!s).map((s) => s.tagName.toLowerCase());
  return [...new Set(tags)];
}

/** Builds the anchor for `el`. Throws only for something that is not an element. */
export function buildAnchor(el: Element): PatchAnchor {
  if (!el || el.nodeType !== 1) throw new Error('buildAnchor needs an element');
  const parent = el.parentElement;
  return {
    cssSelector: buildSelector(el),
    xpath: buildXPath(el),
    textContent: textHint(el),
    attributes: collectAttributes(el),
    // Selector of the immediate parent: the shared matcher tests it with parent.matches(...).
    parentContext: parent && parent.tagName.toLowerCase() !== 'html' ? describe(parent) : '',
    siblingContext: siblingTags(el),
  };
}
